from pathlib import Path
from html import escape
import json, hashlib, base64
ROOT=Path(__file__).parent; D=ROOT/'dist'; ORIGIN='https://un-coup-de-pouce.foamybirch8.chatgpt.site'
HASHES=[]
AR='<span class="arrow" aria-hidden="true">↗</span>'
def button(text,url,cls=''):
 return f'<a class="button {cls}" href="{url}">{text}{AR}</a>'
def shell(path,title,desc,body,en=False):
 lang='en' if en else 'fr'; base='../' if en else ''; home=base+'index.html'
 nav=[('The concept',home+'#concept'),('How it works',home+'#fonctionnement'),('The project','index.html'),('Progress',base+'avancement.html')] if en else [('Le concept','index.html#concept'),('Le fonctionnement','index.html#fonctionnement'),('Le projet','projet.html'),('Avancement','avancement.html')]
 navhtml=''.join(f'<a href="{u}">{t}</a>' for t,u in nav)
 brand=f'<a class="brand" href="{home}" aria-label="Un Coup de Pouce — '+('Home' if en else 'Accueil')+f'"><img src="{base}assets/logo.svg" width="54" height="69" alt="Logo UCP"><span class="brand-name">Un Coup<br>de Pouce.</span></a>'
 footer=f'''<footer class="footer"><div class="wrap"><div class="footer-main"><div>{brand}<p class="footer-mission">{'Every introduction should be useful.' if en else 'Chaque mise en relation doit être utile.'}</p></div><div class="footer-links"><div><strong>{'Explore' if en else 'Découvrir'}</strong><a href="{home}#concept">{'The concept' if en else 'Le concept'}</a><a href="{base}projet.html">{'Our vision' if en else 'Notre vision'}</a><a href="{base}en/index.html" lang="en">Startup overview ↗</a><a href="https://ucp-preproduction.vercel.app">{'Private staging access' if en else 'Préproduction privée'} ↗</a></div><div><strong>{'Useful links' if en else 'Liens utiles'}</strong><a href="{home}#questions">FAQ</a><a href="{base}informations.html">{'Site information & privacy (FR)' if en else 'Informations & confidentialité'}</a><a href="mailto:justeuncoupdepouce@gmail.com">{'Contact the project' if en else 'Contacter le projet'} ↗</a></div></div></div><div class="footer-bottom"><span>© 2026 Un Coup de Pouce · {'Project in preparation · France' if en else 'Projet en préparation · France'}</span><span>{'Company incorporation pending. Platform not yet open.' if en else 'Société en cours de création. Plateforme non ouverte.'}</span></div></div></footer>'''
 canonical=ORIGIN+'/'+path
 graph={'@context':'https://schema.org','@type':'WebPage','name':title,'description':desc,'url':canonical,'inLanguage':lang,'isPartOf':{'@type':'WebSite','name':'Un Coup de Pouce','url':ORIGIN+'/'}}
 graph_json=json.dumps(graph,ensure_ascii=False)
 graph_hash=base64.b64encode(hashlib.sha256(graph_json.encode()).digest()).decode()
 HASHES.append("'sha256-"+graph_hash+"'")
 html=f'''<!doctype html><html lang="{lang}" class="no-js"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{escape(title)}</title><meta name="description" content="{escape(desc)}"><meta name="robots" content="noindex, nofollow"><meta name="theme-color" content="#F5F0EA"><meta name="referrer" content="strict-origin-when-cross-origin"><meta http-equiv="Content-Security-Policy" content="default-src 'self'; script-src 'self' 'sha256-{graph_hash}'; style-src 'self'; img-src 'self' data:; font-src 'self'; connect-src 'none'; object-src 'none'; base-uri 'self'; form-action 'none'; upgrade-insecure-requests"><link rel="canonical" href="{canonical}"><link rel="alternate" hreflang="fr" href="{ORIGIN}/index.html"><link rel="alternate" hreflang="en" href="{ORIGIN}/en/index.html"><link rel="alternate" hreflang="x-default" href="{ORIGIN}/index.html"><meta property="og:type" content="website"><meta property="og:title" content="{escape(title)}"><meta property="og:description" content="{escape(desc)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{ORIGIN}/assets/social.png"><meta property="og:locale" content="{'en_GB' if en else 'fr_FR'}"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="{base}assets/logo.svg" type="image/svg+xml"><link rel="preload" href="{base}assets/fonts/anton.woff2" as="font" type="font/woff2" crossorigin><link rel="preload" href="{base}assets/fonts/montserrat-400.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="{base}assets/style.css"><script type="application/ld+json">{graph_json}</script><script defer src="{base}assets/brief.js"></script><script defer src="{base}assets/app.js"></script></head><body><a class="skip" href="#main">{'Skip to content' if en else 'Aller au contenu'}</a><header class="site-header"><div class="wrap header-inner">{brand}<button class="menu-toggle" type="button" aria-expanded="false" aria-controls="main-nav">Menu <span aria-hidden="true">☰</span></button><nav class="nav" id="main-nav" aria-label="{'Main navigation' if en else 'Navigation principale'}">{navhtml}<a class="lang" href="{base+'index.html' if en else 'en/index.html'}" lang="{'fr' if en else 'en'}" aria-label="{'Version française' if en else 'English project overview'}">{'FR' if en else 'EN'} ↗</a>{button('Explore UCP' if en else 'Découvrir UCP',home+'#demonstration')}</nav></div></header><main id="main">{body}</main>{footer}</body></html>'''
 if path not in ['index.html','en/index.html']:
  import re
  html=re.sub(r'<link rel="alternate"[^>]+>','',html)
 p=D/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(html)

home='''<div class="wrap"><section class="hero" aria-labelledby="hero-title"><div class="hero-copy"><p class="eyebrow"><span class="dot"></span> Des travaux aux bonnes rencontres</p><h1 id="hero-title">Le bon projet.<br>Le bon pro.<br><span>Le déclic.</span></h1><p class="lead">Vos travaux méritent les bons professionnels. Nous construisons une mise en relation plus simple, plus claire, sans commission sur les chantiers.</p><div class="hero-actions">'''+button('Découvrir le fonctionnement','#fonctionnement')+button('Je suis professionnel','#professionnels','outline')+'''</div><p class="fine">Projet français en préparation · Premier terrain envisagé : Toulouse</p></div><div class="hero-art"><div class="art-stage"><img src="assets/house.svg" width="640" height="590" alt="Illustration d’un intérieur en rénovation, avec un canapé bleu-violet et des détails orange."></div><div class="floating-note top"><small>Votre idée</small><strong>Et si on refaisait le salon ?</strong></div><div class="floating-note bottom"><small>Le point de rencontre</small><strong><span class="note-icon" aria-hidden="true">↗</span>Un besoin. Un savoir-faire.</strong></div><div class="round-stamp"><b>0 %</b>de commission<br>sur les travaux</div><p class="art-caption">Illustration du concept · Aucun chantier réel représenté</p></div></section><div class="principles"><span><b class="check" aria-hidden="true">✓</b> Vous gardez le choix</span><span><b class="check" aria-hidden="true">✓</b> Une relation directe</span><span><b class="check" aria-hidden="true">✓</b> Le savoir-faire au premier plan</span></div></div>
<section class="section wrap" id="concept"><div class="section-head"><div><p class="eyebrow">01 / Le point de rencontre</p><h2>Deux besoins.<br>Un coup de pouce.</h2></div><p>D’un côté, un projet qui mérite d’être compris. De l’autre, un professionnel qui veut consacrer son temps aux bonnes demandes. UCP veut rendre cette rencontre plus utile.</p></div><div class="audiences"><article class="audience"><p class="eyebrow">Pour les particuliers</p><h3>Vos idées prennent<br>une direction.</h3><p>Vous ne savez pas toujours quel métier solliciter ni comment présenter vos travaux. UCP est pensé pour vous aider à préciser votre besoin, comparer les profils et choisir avec qui échanger.</p><a class="text-link" href="#demonstration">Essayer un exemple de projet <span aria-hidden="true">↗</span></a><div class="audience-mini"><span class="chip">Un besoin clair</span><span class="chip">Des profils à comparer</span><span class="chip">Votre décision</span></div></article><article class="audience blue" id="professionnels"><p class="eyebrow">Pour les professionnels du BTP</p><h3>Votre savoir-faire.<br>Les projets qui vont avec.</h3><p>Votre métier, votre zone, vos spécialités. Le parcours prévu vous permettra de repérer les demandes adaptées et de choisir celles auxquelles répondre, tout en gardant votre liberté commerciale.</p><a class="text-link" href="#modele">Comprendre le modèle <span aria-hidden="true">↗</span></a><div class="audience-mini"><span class="chip">Visibilité locale</span><span class="chip">Candidature libre</span><span class="chip">Relation directe</span></div></article></div></section>
<section class="section dark" id="fonctionnement"><div class="wrap"><div class="section-top"><div><p class="eyebrow">02 / Le fonctionnement prévu</p><h2>On prépare la rencontre.<br>Vous gardez la main.</h2></div><div class="switch" role="tablist" aria-label="Choisir un point de vue"><button type="button" id="tab-particulier" role="tab" aria-selected="true" aria-controls="panel-particulier" tabindex="0">Particulier</button><button type="button" id="tab-pro" role="tab" aria-selected="false" aria-controls="panel-pro" tabindex="-1">Professionnel</button></div></div><div id="panel-particulier" role="tabpanel" aria-labelledby="tab-particulier" tabindex="0"><div class="steps"><article class="step"><div class="step-num">01</div><div class="step-copy"><h3>Préciser votre projet</h3><p>Nature des travaux, zone, délai et informations utiles : une demande claire donne aux professionnels les bons repères.</p></div></article><article class="step"><div class="step-num">02</div><div class="step-copy"><h3>Découvrir les candidatures</h3><p>Les professionnels intéressés choisissent de répondre. Vous comparez leurs compétences et les éléments de leur profil.</p></div></article><article class="step"><div class="step-num">03</div><div class="step-copy"><h3>Choisir, puis échanger</h3><p>Vous décidez avec qui avancer. Devis, rendez-vous et paiement des travaux restent directement entre vous et le professionnel.</p></div></article></div></div><div id="panel-pro" role="tabpanel" aria-labelledby="tab-pro" tabindex="0" hidden><div class="steps"><article class="step"><div class="step-num">01</div><div class="step-copy"><h3>Présenter votre métier</h3><p>Votre activité, vos spécialités, votre zone d’intervention et vos réalisations donnent du sens à votre profil.</p></div></article><article class="step"><div class="step-num">02</div><div class="step-copy"><h3>Choisir vos projets</h3><p>Vous candidatez aux demandes qui correspondent à votre savoir-faire et à votre disponibilité. Vous restez libre de répondre.</p></div></article><article class="step"><div class="step-num">03</div><div class="step-copy"><h3>Créer une relation directe</h3><p>Après sélection, un abonnement professionnel actif permettra l’échange. Vos devis et vos paiements resteront entre vous et votre client.</p></div></article></div></div><p class="section-note">Ces parcours présentent le fonctionnement envisagé. La plateforme n’est pas encore ouverte aux utilisateurs.</p><noscript><p class="no-js">Le parcours professionnel : présenter son métier, choisir ses projets, puis échanger après sélection avec un abonnement actif.</p></noscript></div></section>
<section class="section wrap" id="demonstration"><div class="section-head"><div><p class="eyebrow">03 / Essayez le principe</p><h2>Un projet bien posé,<br>ça change tout.</h2></div><p>Quelques précisions suffisent à rendre une idée plus lisible. Construisez un exemple de brief et gardez-le pour vous.</p></div><div class="demo"><div class="demo-input"><p class="eyebrow"><span class="dot"></span> Atelier de préparation</p><h3>Votre point de départ.</h3><form id="brief-form"><label class="field" for="project-type">Quel type de travaux ?<select id="project-type" name="type"><option value="peinture">Rafraîchir les murs d’une pièce</option><option value="salle-de-bain">Rénover une salle de bain</option><option value="menuiserie">Créer un rangement sur mesure</option><option value="electricite">Repenser l’éclairage d’une pièce</option></select></label><label class="field" for="project-state">Où en est votre réflexion ?<select id="project-state" name="state"><option value="idee">J’explore encore les possibilités</option><option value="precis">J’ai une idée assez précise</option><option value="defini">Le besoin est défini</option></select></label><label class="field" for="project-timing">Quel horizon envisagez-vous ?<select id="project-timing" name="timing"><option value="flexible">Je suis flexible</option><option value="trois-mois">Dans les trois prochains mois</option><option value="six-mois">Dans les six prochains mois</option></select></label><button class="button" type="submit">Préparer mon exemple <span class="arrow" aria-hidden="true">↗</span></button></form><p class="fine">Démonstration locale, sans IA ni envoi à un professionnel. Aucun projet n’est publié et aucune donnée personnelle n’est demandée.</p><noscript><p class="no-js">Activez JavaScript pour personnaliser et télécharger ce brief. L’exemple reste consultable ci-contre.</p></noscript></div><div class="demo-result"><div class="result-head"><b>Un brief plus clair</b><span>EXEMPLE · NON PUBLIÉ</span></div><div class="brief" id="brief-result"><p class="eyebrow">Mon projet de travaux</p><h3 id="brief-title">Rafraîchir les murs d’une pièce</h3><dl><div><dt>Métier à explorer</dt><dd id="brief-trade">Peinture intérieure</dd></div><div><dt>Maturité</dt><dd id="brief-state">J’explore encore les possibilités</dd></div><div><dt>Horizon</dt><dd id="brief-timing">Je suis flexible</dd></div></dl><p class="field">Pour aller plus loin</p><ul class="brief-checklist" id="brief-checklist"><li>Estimer la surface à peindre et préciser l’état des supports.</li><li>Préparer des photos de la pièce et des murs.</li><li>Décrire les couleurs et finitions envisagées.</li></ul></div><div class="result-actions"><button type="button" id="copy-brief">Copier le brief ↗</button><button type="button" id="download-brief">Télécharger en .txt ↓</button></div><p class="status" role="status" aria-live="polite" id="brief-status"></p><p class="fine">Ce support aide à préparer un échange. Il ne constitue ni un devis, ni un diagnostic technique.</p></div></div></section>
<section class="section wrap zero-section" id="modele"><div><div class="giant-zero" aria-label="Zéro pour cent">0<span>%</span></div><p class="zero-label">de commission sur les travaux</p></div><div class="zero-copy"><p class="eyebrow">04 / Un modèle lisible</p><h2>Votre chantier.<br>Votre relation.</h2><p>UCP prévoit de se rémunérer par un abonnement professionnel. Aucun pourcentage sur le devis, l’acompte ou le montant final des travaux. Aucun paiement à l’unité pour ouvrir une conversation.</p><div class="pricing-line"><div><strong>Particuliers</strong><small>Utilisation prévue gratuite.</small></div><div><strong>Professionnels</strong><small>Un abonnement mensuel.</small></div></div><a class="text-link" href="projet.html#modele-economique">Voir le modèle et les tarifs prévus <span aria-hidden="true">↗</span></a><p class="fine">Aucune offre souscriptible ni facturation sur cette vitrine.</p></div></section>
<section class="section ai-section"><div class="wrap ai-layout"><div class="ai-copy"><p class="eyebrow">05 / Notre vision de l’IA</p><h2>Mieux se comprendre.<br>Avant de se rencontrer.</h2><p>Nous souhaitons explorer l’IA pour aider à structurer une demande, repérer les précisions manquantes et préparer des échanges plus utiles. Les choix restent entre les mains des utilisateurs.</p><a class="text-link" href="projet.html#intelligence-artificielle">Découvrir les usages envisagés <span aria-hidden="true">↗</span></a><p class="fine">Pistes de développement. Intégration Claude non déployée.</p></div><div class="ai-paper"><p class="eyebrow">Un exemple de question utile</p><p class="quote">« Vous souhaitez refaire votre salle de bain. Quels équipements voulez-vous conserver ? »</p><hr><div class="ai-line"><span>1</span>Reformuler le besoin sans le dénaturer.</div><div class="ai-line"><span>2</span>Poser les questions qui manquent.</div><div class="ai-line"><span>3</span>Laisser la personne vérifier et décider.</div><p class="fine">Exemple rédigé pour illustrer la vision, sans appel à une IA.</p></div></div></section>
<section class="section wrap" id="avancement"><div class="section-head"><div><p class="eyebrow">06 / Construire avec méthode</p><h2>Un cap clair.<br>Un lancement à préparer.</h2></div><p>UCP est un projet français en cours de création. Une première base technique existe ; la préparation et la vérification du produit précèdent son ouverture.</p></div><div class="milestones"><article class="milestone current"><p class="eyebrow">Aujourd’hui / En préparation</p><h3>Consolider le produit</h3><p>Clarifier les parcours, récupérer la base technique et préparer les vérifications avant les premiers usages réels.</p></article><article class="milestone"><p class="eyebrow">Prochaine étape / À valider</p><h3>Tester à petite échelle</h3><p>Valider les parcours et l’utilité des mises en relation avant d’envisager une ouverture autour de Toulouse.</p></article><article class="milestone"><p class="eyebrow">À terme / Notre ambition</p><h3>Grandir sur des preuves</h3><p>Étendre progressivement les métiers et les territoires à partir de résultats observés sur le terrain.</p></article></div><a class="text-link" href="projet.html">Comprendre où en est UCP <span aria-hidden="true">↗</span></a></section>
<section class="section wrap faq-layout" id="questions"><div><p class="eyebrow">07 / En toute clarté</p><h2>Les bonnes<br>questions.</h2></div><div class="faq-list">'''
faqs=[('Puis-je déjà publier un projet ou m’inscrire ?','Pas encore. Cette vitrine présente le concept et permet de préparer un exemple de brief. La plateforme et les inscriptions ne sont pas ouvertes ; aucune date de lancement n’est annoncée.'),('Pourquoi « sans commission » ?','Le modèle prévu repose sur des abonnements professionnels et ne prélève aucun pourcentage sur les travaux réalisés. Les devis et paiements du chantier restent directement entre le client et le professionnel.'),('Est-ce gratuit pour un particulier ?','Oui, le modèle prévoit une utilisation gratuite pour les demandeurs. Les tarifs professionnels prévus sont présentés sur la page du projet ; aucune souscription n’est proposée ici.'),('Les professionnels seront-ils vérifiés ?','La vérification des informations professionnelles fait partie des sujets de préparation. Aucun professionnel n’est présenté comme déjà vérifié sur ce site. Un contrôle administratif ne remplace pas l’examen des assurances, références et conditions d’un devis.'),('Quelle place aura l’intelligence artificielle ?','Nous envisageons l’IA comme une aide à la formulation et à la compréhension des demandes. L’intégration reste à développer et à évaluer. La démonstration de cette vitrine fonctionne avec des règles locales, sans IA.'),('UCP est-il déjà une société immatriculée ?','Non. Un Coup de Pouce est un projet de startup française en cours de création. L’immatriculation est prévue dans les prochains mois. La vitrine ne permet ni commande, ni paiement, ni réservation de travaux.')]
for q,a in faqs: home+=f'<details><summary>{q}</summary><p>{a}</p></details>'
home+='''</div></section><div class="wrap"><section class="cta-band"><div><p class="eyebrow">Un projet à comprendre. Une vision à partager.</p><h2>La suite commence<br>par une bonne rencontre.</h2><p>Découvrez ce que nous construisons et les choix qui nous guident.</p></div>'''+button('Découvrir le projet','projet.html','white')+'''</section></div>'''
shell('index.html','Un Coup de Pouce — Travaux et professionnels, sans commission','Découvrez UCP, un projet français de mise en relation entre particuliers et professionnels du BTP, sans commission sur les travaux. Plateforme en préparation.',home)

project='''<div class="wrap"><section class="subhero"><p class="eyebrow">Le projet / France · Pré-lancement</p><h1>Chaque mise en relation<br>doit être utile.</h1><p class="lead">Un Coup de Pouce veut rapprocher des projets mieux exprimés et des professionnels qui choisissent d’y répondre. Un service simple, une relation directe, un modèle transparent.</p><div class="hero-actions">'''+button('Read the startup overview','en/index.html')+button('Voir le concept','index.html#concept','outline')+'''</div></section><section class="editorial"><h2>Le problème<br>à résoudre.</h2><div><h3>Les particuliers manquent de repères.</h3><p>Exprimer un projet, savoir quel métier solliciter et comparer des professionnels peut être difficile. Une demande imprécise complique les premiers échanges.</p><h3>Les professionnels ont besoin de pertinence.</h3><p>Qualifier une demande éloignée de sa zone, de ses compétences ou de son planning mobilise du temps. UCP veut aider chacun à identifier plus tôt les informations qui comptent.</p><p>Ce sont les besoins auxquels le projet entend répondre. Leur ampleur et la valeur de la solution doivent encore être mesurées sur le terrain.</p></div></section><section class="editorial" id="modele-economique"><h2>Un modèle<br>sans détour.</h2><div><p>Le modèle de travail retenu repose sur un abonnement mensuel des professionnels. Les demandeurs utilisent le service gratuitement. UCP ne prélève aucune commission sur les chantiers et ne gère pas le règlement des travaux.</p><div class="table-wrap"><table><caption>Tarification prévue — aucune souscription ouverte</caption><thead><tr><th scope="col">Profil</th><th scope="col">Base mensuelle prévue</th></tr></thead><tbody><tr><th scope="row">Particulier demandeur</th><td>Gratuit</td></tr><tr><th scope="row">Artisan individuel</th><td>29 € HT / mois</td></tr><tr><th scope="row">Entreprise</th><td>20 € HT / mois + 15 € HT par artisan lié</td></tr></tbody></table></div><p class="fine">Exemple : 3 artisans liés correspondent à 65 € HT par mois. Conditions contractuelles à finaliser avant toute commercialisation. Aucun volume de chantiers ni résultat commercial n’est garanti.</p></div></section><section class="editorial" id="intelligence-artificielle"><h2>Une IA utile.<br>Un rôle précis.</h2><div><p><span class="badge">Usages envisagés — non déployés</span></p><h3>1. Aider à formuler le projet</h3><p>Transformer une description libre en un brief structuré : nature des travaux, contexte, contraintes et échéance. Toute reformulation devra être vérifiée et approuvée par le demandeur.</p><h3>2. Faire émerger les informations manquantes</h3><p>Proposer des questions de clarification pertinentes avant la mise en relation, en distinguant les faits donnés par la personne des informations encore inconnues.</p><h3>3. Faciliter la lecture des demandes</h3><p>Préparer une synthèse compréhensible pour les professionnels et explorer une catégorisation des besoins. La pertinence métier et géographique devra rester explicable et contrôlable.</p><h3>Notre piste technique : l’API Claude</h3><p>Nous souhaitons expérimenter l’API Claude pour ces usages de compréhension et de structuration. L’intégration n’est pas active et UCP ne revendique aucun partenariat ni soutien d’Anthropic.</p><p>Le développement devra intégrer la minimisation des données, une validation côté serveur, des réponses structurées et une revue humaine. Aucune clé API ne sera exposée dans le navigateur.</p></div></section><section class="editorial"><h2>Mesurer l’utilité.<br>Garder le contrôle.</h2><div><p>Avant une mise en service, l’évaluation devra comparer les briefs assistés à une version sans IA : informations exactes conservées, ambiguïtés repérées, effort de correction et temps nécessaire pour qualifier la demande.</p><ul><li>Tester d’abord sur des exemples fictifs représentatifs des métiers.</li><li>Signaler les incertitudes et permettre la correction ou le refus de la suggestion.</li><li>Tester les demandes hors périmètre et les instructions malveillantes.</li><li>Contrôler le coût par requête, la latence et le comportement en cas d’indisponibilité.</li></ul><p>L’IA envisagée n’a pas vocation à certifier un artisan, établir un diagnostic technique ou décider d’un contrat à la place des utilisateurs.</p></div></section><section class="editorial" id="stade"><h2>Où nous<br>en sommes.</h2><div><p><a class="badge" href="avancement.html">Situation de pré-lancement · voir les preuves publiques</a></p><h3>Une startup française en cours de création</h3><p>Le projet est porté par Cosme Collomb. La société n’est pas encore juridiquement immatriculée ; sa création officielle est prévue dans les prochains mois.</p><h3>Une première base technique, un produit à vérifier</h3><p>Le travail actuel porte sur la consolidation du produit et la préparation des tests. Cette vitrine est indépendante de l’application de mise en relation. Elle ne donne pas accès à des demandes de travaux réelles.</p><h3>Un premier terrain envisagé autour de Toulouse</h3><p>L’objectif est de valider l’utilité à petite échelle, puis d’étendre progressivement les métiers et les zones couvertes si les résultats le justifient. Aucun calendrier d’expansion ni chiffre de croissance n’est annoncé.</p></div></section><section class="editorial"><h2>Échanger<br>sur le projet.</h2><div><p>Pour une question sur la vision, le fonctionnement prévu ou un échange institutionnel, vous pouvez écrire à l’adresse de contact du projet.</p><p><a class="sources-link" href="mailto:justeuncoupdepouce@gmail.com">justeuncoupdepouce@gmail.com</a></p><p class="fine">Ce contact ne constitue pas une inscription à la plateforme ou une demande de devis. Votre messagerie s’ouvre ; aucun message n’est envoyé automatiquement.</p></div></section><div class="page-ending">'''+button('Revenir à la vitrine','index.html','outline')+button('Startup overview in English','en/index.html')+'''</div></div>'''
shell('projet.html','Le projet UCP — Modèle, stade de développement et vision IA','Le modèle sans commission d’Un Coup de Pouce, son stade de préparation en France et les usages envisagés de l’API Claude.',project)

english='''<div class="wrap"><section class="subhero"><p class="eyebrow">Startup overview / France · Pre-launch</p><h1>Better project briefs.<br>More useful connections.</h1><p class="lead">Un Coup de Pouce (UCP) is building a platform that connects homeowners with building and renovation professionals. Clearer requests, relevant introductions, and no commission on the work carried out.</p><div class="hero-actions">'''+button('Explore the concept','../index.html#concept')+button('Our planned AI use','#planned-ai','outline')+'''</div></section><section class="editorial"><h2>The project<br>in one minute.</h2><div><div class="table-wrap"><table><tbody><tr><th scope="row">Who we serve</th><td>Homeowners planning works, independent tradespeople and building companies.</td></tr><tr><th scope="row">Problem</th><td>Unclear requests make it harder to find suitable professionals and take time to qualify.</td></tr><tr><th scope="row">Product</th><td>A planned workflow for structured project requests, relevant professional applications and user-selected introductions.</td></tr><tr><th scope="row">Business model</th><td>Professional subscriptions. No commission on the value of the work. Free use planned for requesters.</td></tr><tr><th scope="row">Stage</th><td>Pre-launch. An initial technical base exists; product consolidation and testing are being prepared.</td></tr><tr><th scope="row">Legal status</th><td>French startup project. Not yet incorporated; incorporation planned in the coming months.</td></tr><tr><th scope="row">Initial focus</th><td>A local validation phase around Toulouse, before considering wider coverage.</td></tr></tbody></table></div></div></section><section class="editorial"><h2>A useful<br>introduction.</h2><div><h3>Homeowners explain their needs.</h3><p>The planned experience helps people describe the type of work, location, timing and practical constraints. Professionals can understand the request before deciding whether to respond.</p><h3>Professionals choose their opportunities.</h3><p>Tradespeople present their skills and service area, then apply to relevant requests. The homeowner chooses whom to engage with. Quotes, deposits and payments for the work remain directly between the parties.</p><p>The platform is not yet open. This website presents the intended experience; it does not offer live job requests, sign-ups or payments.</p></div></section><section class="editorial" id="planned-ai"><h2>Why we want<br>to build with Claude.</h2><div><p><span class="badge">Planned exploration — not integrated</span></p><h3>Turn free text into a clear project brief.</h3><p>We intend to explore the Claude API to structure a homeowner’s description, preserve their stated requirements and identify information that is still missing.</p><h3>Ask useful clarification questions.</h3><p>We want to help users explain their needs without requiring them to know technical trade vocabulary. Users would review and approve any proposed wording before it could be shared.</p><h3>Make requests easier to understand.</h3><p>We plan to assess summaries and request categorisation to help professionals qualify opportunities. Trade and location criteria should remain explicit and inspectable.</p><p>These are planned product capabilities, not deployed features. The interactive brief on the French homepage uses local, predefined rules and makes no AI API calls.</p></div></section><section class="editorial"><h2>Evaluate first.<br>Keep people in charge.</h2><div><p>Our proposed development approach starts with fictional examples, a non-AI baseline and human review. We would evaluate factual fidelity, missed constraints, unnecessary questions, correction effort, latency and cost per completed brief.</p><p>Before production, the integration would need server-side API access, data minimisation, output validation, prompt-injection testing, bounded requests and a usable fallback when the model is unavailable.</p><p>AI would assist communication. It would not certify contractors, diagnose building safety, guarantee project outcomes or make contracting decisions for users.</p></div></section><section class="editorial"><h2>A model<br>built for clarity.</h2><div><p>The planned pricing is €29 excluding VAT per month for an independent professional, or €20 excluding VAT per month plus €15 per linked tradesperson for a company account. Requester use is planned to be free.</p><p>There is no per-conversation charge in the current model and no percentage taken from renovation contracts. Contractual terms must be finalised before commercial launch.</p><p>Our growth approach is to validate the usefulness of introductions locally, then expand by trade and geography where evidence supports it. We are not claiming active customers, revenue, partnerships or measured traction.</p></div></section><section class="editorial"><h2>Founder<br>& current stage.</h2><div><h3>Cosme Collomb · Project founder</h3><p>UCP is a French startup project being prepared for market validation. An initial technical base exists. Its consolidation, verification and controlled testing are the next product milestones.</p><p>The company is not yet legally incorporated. Incorporation is planned in the coming months. This status is stated openly in our project presentation.</p><p>We are preparing to apply for startup support to explore and evaluate these AI use cases. UCP is not an Anthropic partner or an accepted Claude Startups member.</p><p class="fine">Current evidence and delivery limits are recorded in the <a href="../avancement.html">project progress report (FR)</a>.</p></div></section><div class="cta-band"><div><p class="eyebrow">A conversation about what comes next</p><h2>Every introduction<br>should be useful.</h2><p>Questions about UCP, the product or our planned AI use?</p></div>'''+button('Contact the project','mailto:justeuncoupdepouce@gmail.com','white')+'''</div></div>'''
shell('en/index.html','Un Coup de Pouce — Startup overview & planned Claude API use','UCP is a pre-launch French startup project connecting homeowners and building professionals, with no commission on works and planned AI-assisted project briefs.',english,True)

info='''<div class="wrap"><section class="subhero"><p class="eyebrow">Informations sur cette vitrine</p><h1>Comprendre ce site.<br>Et ses limites actuelles.</h1><p class="lead">Cette version de présentation est destinée à la revue du projet. Elle est distincte de la future plateforme de mise en relation.</p></section><section class="editorial"><h2>Le projet.</h2><div><p>Nom : Un Coup de Pouce (UCP). Porteur du projet : Cosme Collomb. Statut : projet français en cours de création, société non encore immatriculée.</p><p>Contact du projet identifié dans les documents UCP : <a class="sources-link" href="mailto:justeuncoupdepouce@gmail.com">justeuncoupdepouce@gmail.com</a>.</p><p>Cette page ne constitue pas des mentions légales complètes pour une ouverture publique. L’identification complète de l’éditeur, les informations de contact définitives et les mentions d’hébergement doivent être confirmées avant la diffusion publique sur le domaine UCP.</p></div></section><section class="editorial"><h2>La démonstration.</h2><div><p>Le générateur de brief fonctionne uniquement dans votre navigateur avec des contenus prédéfinis. Il n’utilise pas d’intelligence artificielle, ne publie aucun projet, ne contacte aucun professionnel et ne transmet pas vos sélections à une API.</p><p>Les sélections ne sont pas conservées par le code du site après rechargement de la page. « Copier » utilise le presse-papiers de votre appareil. « Télécharger » crée un fichier texte sur votre appareil.</p><p>Aucun formulaire d’inscription, paiement, compte utilisateur ou collecte de coordonnées n’est mis en place dans cette vitrine.</p></div></section><section class="editorial"><h2>Confidentialité.</h2><div><p>Le code de la vitrine n’ajoute aucun traceur publicitaire, outil de mesure d’audience ou cookie applicatif. Les polices, styles, scripts et illustrations sont servis avec le site.</p><p>Le service d’hébergement peut traiter des données techniques nécessaires à l’accès et à la sécurité. Les conditions propres à ce service restent applicables ; l’absence de traceurs dans la vitrine ne signifie pas l’absence de journaux techniques de l’hébergeur.</p><p>Un clic sur un lien e-mail ouvre votre messagerie. Si vous choisissez d’envoyer un message, il sera traité par votre fournisseur de messagerie et par celui du destinataire. Ne transmettez pas de documents sensibles par ce simple contact de présentation.</p></div></section><section class="editorial"><h2>Contenus<br>et statut.</h2><div><p>Le logo est repris du document officiel de charte UCP Ydays 2025–2026. Les couleurs principales sont #FF791D et #505DC1 ; les polices sont Anton et Montserrat, distribuées sous licence libre SIL Open Font License.</p><p>Le dessin d’intérieur et les exemples de briefs sont des illustrations du concept. Ils ne représentent ni un chantier réalisé via UCP, ni un professionnel inscrit, ni une réponse produite par Claude.</p><p>Aucun lien de partenariat avec Anthropic n’est revendiqué. Les capacités IA sont des pistes de développement à évaluer.</p></div></section><div class="page-ending">'''+button('Retour à la vitrine','index.html')+'''</div></div>'''
shell('informations.html','Informations & confidentialité — Un Coup de Pouce','Informations sur le projet UCP, le fonctionnement local de la démonstration et la confidentialité de la vitrine de présentation.',info)
error='''<div class="wrap error-page"><div><p class="eyebrow">Page introuvable / 404</p><h1>Reprenons<br>le bon chemin.</h1><p>Cette page n’existe pas ou a été déplacée.</p><div class="hero-actions">'''+button('Revenir à l’accueil','index.html')+'''</div></div></div>'''
shell('404.html','Page introuvable — Un Coup de Pouce','Revenir à la présentation du projet Un Coup de Pouce.',error)
